from PySide6 import QtWidgets
from PySide6.QtCore import QMetaObject, QSize, Qt
from PySide6.QtGui import QIcon
from PySide6.QtWidgets import QLabel, QLineEdit, QPushButton, QSizePolicy, QHBoxLayout, QVBoxLayout, QDialog

from videotrans.configure.config import tr, ROOT_DIR,params
from pathlib import Path
from videotrans.util.help_misc import open_url

class Ui_audiocpp(QDialog):
    def __init__(self):
        super().__init__()
        self.setWindowIcon(QIcon(f"{ROOT_DIR}/videotrans/styles/icon.ico"))
        self.setupUi(self)

    def setupUi(self, form):
        self.has_done = False
        form.setObjectName("form")
        form.resize(600, 250)

        v1 = QVBoxLayout(form)       

        label_4 = QtWidgets.QLabel()
        label_4.setWordWrap(True)
        label_4.setObjectName("label_4")
        label_4.setText(tr('use admin run'))
        label_4.setMinimumSize(QSize(0, 40))
        v1.addWidget(label_4)

        h3 = QHBoxLayout()
        h4 = QHBoxLayout()
        label_3 = QtWidgets.QLabel()
        label_3.setObjectName("label_3")
        label_3.setText(tr('Select the model for dubbing'))
        self.model = QtWidgets.QComboBox()
        self.model.setMinimumSize(QSize(0, 35))
        self.model.setObjectName("model")
        h3.addWidget(label_3)
        h3.addWidget(self.model)
        v1.addLayout(h3)

        self.loglable = QtWidgets.QLabel()
        self.loglable.setWordWrap(True)
        self.loglable.setObjectName("self.loglable")
        self.loglable.setText('')
        self.loglable.setStyleSheet('color:#aaaaaa')
        self.loglable.setMinimumSize(QSize(0, 40))
        v1.addWidget(self.loglable)
        

        self.save = QPushButton()
        self.save.setObjectName("save")
        self.save.setMinimumSize(QSize(0, 35))

        self.test = QPushButton()
        self.test.setObjectName("test")
        self.test.setMinimumSize(QSize(0, 35))
        
        help_btn = QtWidgets.QPushButton()
        help_btn.setMinimumSize(QSize(0, 35))
        help_btn.setStyleSheet("background-color: rgba(255, 255, 255,0)")
        help_btn.setObjectName("help_btn")
        help_btn.setCursor(Qt.PointingHandCursor)
        help_btn.setText(tr("Fill out the tutorial"))
        help_btn.clicked.connect(lambda: open_url(url='https://pyvideotrans.com/audiocpp'))
        
        h4.addWidget(self.save)
        h4.addWidget(self.test)
        h4.addWidget(help_btn)



        v1.addLayout(h4)
        v1.addStretch()


        self.retranslateUi(form)
        QMetaObject.connectSlotsByName(form)
    
    def update_ui(self):
        import json
        jsondata=json.loads(Path(f'{ROOT_DIR}/videotrans/voicejson/audiocpp.json').read_text(encoding='utf-8'))
        self.model.clear()
        self.model.addItems(list(jsondata.keys()))
        _current_model=params.get('audiocpp_model','omnivoice')
        self.model.setCurrentText(_current_model)
        support_languages=jsondata.get(_current_model,{}).get('support_languages')
        if support_languages:
            self.loglable.setText(f"{_current_model} {tr('Only support')} "+(",".join([tr(code) for code in support_languages])))


    def retranslateUi(self, form):
        form.setWindowTitle("Audio.cpp")
        self.save.setText(tr("Save"))
        self.test.setText(tr("Test"))
